  const resp = String(o.respuesta_matias || o.respuesta || o.respuestaBot || '').trim();
  if (!msg || !resp) return null;
  return {
    fecha: o.fecha || new Date().toISOString(),
    canal: String(o.canal || 'desconocido'),
    contexto_cliente: msg.slice(0, 500),
